namespace ghidra.app.plugin.core.compositeeditor;



using docking;
using docking.action;
using generic.theme;

/**
 * {@link RedoChangeAction} facilitates an redo of recently undone/reverted composite editor changes.
 */
public class RedoChangeAction : CompositeEditorTableAction {

	public static string DESCRIPTION = "Redo Change";
	public static string ACTION_NAME = "Redo Editor Change";
	private static string GROUP_NAME = UNDOREDO_ACTION_GROUP;
	private static Icon ICON = new GIcon("icon.redo");
	private static string[] POPUP_PATH = new string[] { DESCRIPTION };

	public RedoChangeAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {
		setKeyBindingData(new KeyBindingData("ctrl shift Z"));
		setDescription("Redo editor change");
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		CompositeViewerDataTypeManager<object> viewDTM = model.getViewDataTypeManager();
		viewDTM.redo();

		model.clearStatus();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (hasIncompleteFieldEntry()) {
			return false;
		}
		CompositeViewerDataTypeManager<object> viewDTM = model.getViewDataTypeManager();
		bool canRedo = viewDTM.canRedo();
		setEnabled(canRedo);
		string description = DESCRIPTION + (canRedo ? (": " + viewDTM.getRedoName()) : "");
		setDescription(description);
		return canRedo;
	}
}
